  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.loja.controller.*;
  7	import com.loja.repository.*;
  8	import com.loja.service.*;
  9	import com.loja.service.club.ClubBenefitsCalculator;
 10	import com.loja.service.coupon.CouponService;
 11	import com.loja.service.insurance.InsuranceCalculator;
 12	import com.loja.service.payment.PaymentAdjustmentCalculator;
 13	import com.loja.service.shipping.ShippingCalculator;
 14	import com.loja.service.shipping.TransLogClient;
 15	import io.javalin.Javalin;
 16	import io.javalin.json.JavalinJackson;
 17	
 18	public class Application {
 19	    public static void main(String[] args) {
 20	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/loja");
 21	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 22	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 23	        String transLogUrl = System.getenv().getOrDefault("TRANSLOG_URL", "http://localhost:8081");
 24	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
 25	
 26	        Database database = new Database(dbUrl, dbUser, dbPassword);
 27	
 28	        ObjectMapper objectMapper = new ObjectMapper();
 29	        objectMapper.registerModule(new JavaTimeModule());
 30	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 31	
 32	        ProductRepository productRepository = new ProductRepository(database);
 33	        CustomerRepository customerRepository = new CustomerRepository(database);
 34	        OrderRepository orderRepository = new OrderRepository(database, objectMapper);
 35	        NotificationRepository notificationRepository = new NotificationRepository(database);
 36	
 37	        productRepository.initializeCatalog();
 38	
 39	        TransLogClient transLogClient = new TransLogClient(transLogUrl);
 40	        CouponService couponService = new CouponService();
 41	        ShippingCalculator shippingCalculator = new ShippingCalculator(transLogClient);
 42	        InsuranceCalculator insuranceCalculator = new InsuranceCalculator();
 43	        PaymentAdjustmentCalculator paymentAdjustmentCalculator = new PaymentAdjustmentCalculator();
 44	        ClubBenefitsCalculator clubBenefitsCalculator = new ClubBenefitsCalculator();
 45	
 46	        CheckoutService checkoutService = new CheckoutService(
 47	            productRepository,
 48	            orderRepository,
 49	            couponService,
 50	            shippingCalculator,
 51	            insuranceCalculator,
 52	            paymentAdjustmentCalculator,
 53	            clubBenefitsCalculator
 54	        );
 55	
 56	        OrderService orderService = new OrderService(
 57	            database,
 58	            orderRepository,
 59	            productRepository,
 60	            customerRepository,
 61	            notificationRepository,
 62	            checkoutService
 63	        );
 64	
 65	        CheckoutController checkoutController = new CheckoutController(checkoutService);
 66	        OrderController orderController = new OrderController(orderService);
 67	        ProductController productController = new ProductController(productRepository);
 68	        CustomerController customerController = new CustomerController(customerRepository, notificationRepository);
 69	
 70	        Javalin app = Javalin.create(config -> {
 71	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 72	        }).start(port);
 73	
 74	        app.post("/checkout/summary", checkoutController::calculateSummary);
 75	        app.post("/orders", orderController::createOrder);
 76	        app.get("/orders/{id}", orderController::getOrder);
 77	        app.post("/orders/{id}/payment", orderController::processPayment);
 78	        app.post("/orders/{id}/shipment", orderController::shipOrder);
 79	        app.post("/orders/{id}/delivery", orderController::deliverOrder);
 80	        app.post("/orders/{id}/cancellation", orderController::cancelOrder);
 81	        app.get("/products/{sku}", productController::getProduct);
 82	        app.get("/customers/{cpf}", customerController::getCustomer);
 83	        app.get("/customers/{cpf}/notifications", customerController::getCustomerNotifications);
 84	        app.post("/notifications/{id}/read", customerController::markNotificationAsRead);
 85	
 86	        System.out.println("Server started on port " + port);
 87	    }
 88	}
