 91	import com.loja.domain.CheckoutRequest;
 92	import com.loja.domain.CheckoutSummary;
 93	import com.loja.service.CheckoutService;
 94	import com.loja.util.ApiException;
 95	import io.javalin.http.Context;
 96	
 97	import java.sql.SQLException;
 98	import java.util.Map;
 99	
100	public class CheckoutController {
101	    private final CheckoutService checkoutService;
102	
103	    public CheckoutController(CheckoutService checkoutService) {
104	        this.checkoutService = checkoutService;
105	    }
106	
107	    public void calculateSummary(Context ctx) {
108	        try {
109	            CheckoutRequest request = ctx.bodyAsClass(CheckoutRequest.class);
110	            CheckoutSummary summary = checkoutService.calculateSummary(request);
111	            ctx.status(200).json(summary);
