119	package com.loja.controller;
120	
121	import com.loja.domain.Customer;
122	import com.loja.domain.Notification;
123	import com.loja.repository.CustomerRepository;
124	import com.loja.repository.NotificationRepository;
125	import com.loja.util.ApiException;
126	import io.javalin.http.Context;
127	
128	import java.util.List;
129	import java.util.Map;
130	
131	public class CustomerController {
132	    private final CustomerRepository customerRepository;
133	    private final NotificationRepository notificationRepository;
134	
135	    public CustomerController(CustomerRepository customerRepository, NotificationRepository notificationRepository) {
136	        this.customerRepository = customerRepository;
137	        this.notificationRepository = notificationRepository;
138	    }
139	
140	    public void getCustomer(Context ctx) {
141	        try {
142	            String cpf = ctx.pathParam("cpf");
143	            Customer customer = customerRepository.findByCpf(cpf)
144	                .orElseThrow(() -> new ApiException("CUSTOMER_NOT_FOUND", 404));
145	            ctx.status(200).json(customer);
146	        } catch (ApiException e) {
147	            ctx.status(e.getHttpStatus()).json(Map.of("error", e.getErrorCode()));
148	        }
149	    }
150	
151	    public void getCustomerNotifications(Context ctx) {
152	        try {
153	            String cpf = ctx.pathParam("cpf");
154	            if (customerRepository.findByCpf(cpf).isEmpty()) {
155	                throw new ApiException("CUSTOMER_NOT_FOUND", 404);
156	            }
157	            List<Notification> notifications = notificationRepository.findByCustomerCpf(cpf);
158	            ctx.status(200).json(notifications);
159	        } catch (ApiException e) {
160	            ctx.status(e.getHttpStatus()).json(Map.of("error", e.getErrorCode()));
161	        }
162	    }
163	
164	    public void markNotificationAsRead(Context ctx) {
165	        try {
166	            String notificationId = ctx.pathParam("id");
167	            Notification notification = notificationRepository.findById(notificationId)
168	                .orElseThrow(() -> new ApiException("NOTIFICATION_NOT_FOUND", 404));
169	
170	            notificationRepository.markAsRead(notificationId);
171	            notification.setStatus(com.loja.domain.NotificationStatus.READ);
172	            ctx.status(200).json(notification);
173	        } catch (ApiException e) {
174	            ctx.status(e.getHttpStatus()).json(Map.of("error", e.getErrorCode()));
175	        }
176	    }
177	}
