213	            couponDiscount = couponService.applyCap(couponDiscount, productsSubtotal);
214	        }
215	
216	        ShippingResult shippingResult = shippingCalculator.calculate(request, productMap);
217	        BigDecimal shippingCost = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
218	            ? BigDecimal.ZERO
219	            : shippingResult.getCost();
