223	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
224	
225	        BigDecimal paymentAdjustment = paymentAdjustmentCalculator.calculate(orderTotal, request.getPaymentMethod(), installments, request.getCoupon() != null && !request.getCoupon().isEmpty());
226	        BigDecimal finalTotal = orderTotal.add(paymentAdjustment);
227	
228	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP && finalTotal.compareTo(new BigDecimal("1000.00")) > 0) {
229	            throw new ApiException("PAYMENT_METHOD_UNAVAILABLE", 422);
230	        }
