233	    private BigDecimal calculateProductsSubtotal(List<OrderItem> items, Map<String, Product> productMap) {
234	        BigDecimal total = BigDecimal.ZERO;
235	        for (OrderItem item : items) {
236	            Product product = productMap.get(item.getSku());
237	            total = total.add(product.getPrice().multiply(new BigDecimal(item.getQuantity())));
238	        }
239	        return total;
240	    }
