320	    public Order processPayment(String orderId, String transactionId, Instant paidAt) {
321	        try (Connection conn = database.getConnection()) {
322	            conn.setAutoCommit(false);
323	            try {
324	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
325	                if (existingOrder.isEmpty()) {
326	                    conn.rollback();
327	                    throw new ApiException("ORDER_NOT_FOUND", 404);
328	                }
329	
330	                Order order = existingOrder.get();
331	
332	                if (transactionId == null || transactionId.isEmpty() || paidAt == null) {
333	                    conn.rollback();
334	                    throw new ApiException("INVALID_ORDER", 422);
335	                }
336	
337	                boolean isNewTransaction = orderRepository.recordPaymentTransaction(orderId, transactionId, paidAt, conn);
338	
339	                if (!isNewTransaction) {
340	                    conn.rollback();
341	                    return order;
342	                }
343	
344	                if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
345	                    conn.rollback();
346	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
347	                }
348	
349	                Duration elapsed = Duration.between(order.getCreatedAt(), paidAt);
350	                if (elapsed.compareTo(Duration.ofHours(48)) > 0) {
351	                    orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
352	                    order.setStatus(OrderStatus.CANCELLED);
353	                    notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
354	                    conn.commit();
355	                    throw new ApiException("ORDER_EXPIRED", 409);
356	                }
357	
358	                Map<String, Integer> skuQuantities = new HashMap<>();
359	                for (OrderItem item : order.getItems()) {
360	                    skuQuantities.put(item.getSku(), item.getQuantity());
361	                }
362	
363	                try {
364	                    productRepository.decreaseStock(skuQuantities, conn);
365	                } catch (SQLException e) {
366	                    if (e.getMessage().equals("INSUFFICIENT_STOCK")) {
367	                        orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
368	                        order.setStatus(OrderStatus.CANCELLED);
369	                        notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
370	                        conn.commit();
371	                        throw new ApiException("INSUFFICIENT_STOCK", 409);
372	                    }
373	                    throw e;
374	                }
375	
376	                if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
377	                    customerRepository.addCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit(), conn);
378	                }
379	
380	                orderRepository.updateStatus(orderId, OrderStatus.PAID, conn);
381	                orderRepository.updatePaymentTransaction(orderId, transactionId, conn);
382	                order.setStatus(OrderStatus.PAID);
383	                order.setPaymentTransactionId(transactionId);
384	
385	                notificationRepository.create(order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId, conn);
386	
387	                conn.commit();
388	                return order;
389	            } catch (ApiException e) {
390	                conn.rollback();
391	                throw e;
392	            } catch (Exception e) {
393	                conn.rollback();
394	                throw new RuntimeException("Failed to process payment", e);
395	            }
396	        } catch (SQLException e) {
397	            throw new RuntimeException("Database connection failed", e);
398	        }
399	    }
