 71	
 72	            ShippingResult shippingForCoupon = shippingCalculator.calculate(request, productMap);
 73	            BigDecimal preliminaryShipping = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
 74	                ? BigDecimal.ZERO
 75	                : shippingForCoupon.getCost();
 76	
 77	            couponDiscount = coupon.calculateDiscount(productsSubtotal, preliminaryShipping, request.getItems(), productMap);
 78	            couponDiscount = couponService.applyCap(couponDiscount, productsSubtotal);
 79	        }
 80	
 81	        ShippingResult shippingResult = shippingCalculator.calculate(request, productMap);
 82	        BigDecimal shippingCost = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
 83	            ? BigDecimal.ZERO
 84	            : shippingResult.getCost();
 85	        int deliveryDays = shippingResult.getDeliveryDays();
 86	
 87	        BigDecimal insurance = insuranceCalculator.calculate(productsSubtotal, request.getRegion());
 88	
 89	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
 90	
 91	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
 92	        BigDecimal paymentAdjustment = paymentAdjustmentCalculator.calculate(orderTotal, request.getPaymentMethod(), installments, hasCoupon);
 93	
 94	        BigDecimal finalTotal = orderTotal.add(paymentAdjustment);
 95	        BigDecimal installmentAmount = paymentAdjustmentCalculator.calculateInstallmentAmount(finalTotal, installments);
 96	
 97	        BigDecimal nextPurchaseCredit = clubBenefitsCalculator.calculateCredit(productsSubtotal, request.getClubTier());
 98	        boolean gift = clubBenefitsCalculator.hasGift(request.getClubTier(), productsSubtotal);
 99	
100	        CheckoutSummary summary = new CheckoutSummary();
101	        summary.setProductsSubtotal(productsSubtotal);
102	        summary.setCouponDiscount(couponDiscount);
103	        summary.setShippingCost(shippingCost);
104	        summary.setDeliveryDays(deliveryDays);
105	        summary.setInsurance(insurance);
106	        summary.setPaymentAdjustment(paymentAdjustment);
107	        summary.setFinalTotal(finalTotal);
108	        summary.setInstallments(installments);
109	        summary.setInstallmentAmount(installmentAmount);
110	        summary.setNextPurchaseCredit(nextPurchaseCredit);
111	        summary.setGift(gift);
112	
113	        return summary;
114	    }
115	
116	    private void validateRequest(CheckoutRequest request, Connection conn) throws SQLException {
117	        if (request.getItems() == null || request.getItems().isEmpty()) {
118	            throw new ApiException("INVALID_ORDER", 422);
119	        }
120	
121	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null || request.getCustomer().getEmail() == null) {
122	            throw new ApiException("INVALID_ORDER", 422);
123	        }
124	
125	        Set<String> seenSkus = new HashSet<>();
126	        for (OrderItem item : request.getItems()) {
127	            if (item.getSku() == null || item.getSku().isEmpty()) {
128	                throw new ApiException("INVALID_ORDER", 422);
129	            }
130	            if (item.getQuantity() <= 0) {
131	                throw new ApiException("INVALID_ORDER", 422);
132	            }
133	            if (!seenSkus.add(item.getSku())) {
134	                throw new ApiException("INVALID_ORDER", 422);
135	            }
136	        }
137	
138	        Set<String> skus = new HashSet<>();
139	        for (OrderItem item : request.getItems()) {
140	            skus.add(item.getSku());
141	        }
142	        Map<String, Product> productMap = productRepository.findBySkus(skus);
143	
144	        for (String sku : skus) {
145	            if (!productMap.containsKey(sku)) {
146	                throw new ApiException("UNKNOWN_PRODUCT", 422);
147	            }
148	        }
149	
150	        for (OrderItem item : request.getItems()) {
151	            Product product = productMap.get(item.getSku());
152	            if (product.isDiscontinued()) {
153	                throw new ApiException("PRODUCT_DISCONTINUED", 422);
154	            }
155	            if (product.getStock() < item.getQuantity()) {
156	                throw new ApiException("INSUFFICIENT_STOCK", 422);
157	            }
158	        }
159	
160	        if (request.getClubTier() == null) {
161	            throw new ApiException("INVALID_CLUB_TIER", 422);
162	        }
163	
164	        if (request.getRegion() == null) {
165	            throw new ApiException("INVALID_REGION", 422);
166	        }
167	
168	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
169	            throw new ApiException("INVALID_ZIP_CODE", 422);
170	        }
171	
172	        if (request.getShippingMethod() == null) {
173	            throw new ApiException("INVALID_SHIPPING_METHOD", 422);
174	        }
175	
176	        if (request.getCoupon() != null && !request.getCoupon().isEmpty() && !couponService.exists(request.getCoupon())) {
177	            throw new ApiException("INVALID_COUPON", 422);
178	        }
179	
180	        if (request.getPaymentMethod() == null) {
181	            throw new ApiException("INVALID_PAYMENT_METHOD", 422);
182	        }
183	
184	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
185	        if (request.getPaymentMethod() == PaymentMethod.PIX || request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
186	            if (installments != 1) {
187	                throw new ApiException("INVALID_INSTALLMENTS", 422);
188	            }
189	        } else if (request.getPaymentMethod() == PaymentMethod.CREDIT_CARD) {
190	            if (installments < 1 || installments > 12) {
191	                throw new ApiException("INVALID_INSTALLMENTS", 422);
192	            }
193	        }
194	
195	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), productMap);
196	        productsSubtotal = MoneyUtils.roundMoney(productsSubtotal);
197	
198	        boolean isFirstPurchase = conn == null || !orderRepository.hasCompletedOrders(request.getCustomer().getCpf(), conn);
199	
200	        BigDecimal couponDiscount = BigDecimal.ZERO;
201	        if (request.getCoupon() != null && !request.getCoupon().isEmpty()) {
202	            CouponStrategy coupon = couponService.getCoupon(request.getCoupon());
203	            if (!coupon.isApplicable(request, productMap, isFirstPurchase)) {
204	                return;
205	            }
206	
207	            ShippingResult shippingForCoupon = shippingCalculator.calculate(request, productMap);
208	            BigDecimal preliminaryShipping = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
209	                ? BigDecimal.ZERO
210	                : shippingForCoupon.getCost();
211	
212	            couponDiscount = coupon.calculateDiscount(productsSubtotal, preliminaryShipping, request.getItems(), productMap);
213	            couponDiscount = couponService.applyCap(couponDiscount, productsSubtotal);
214	        }
215	
216	        ShippingResult shippingResult = shippingCalculator.calculate(request, productMap);
217	        BigDecimal shippingCost = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
218	            ? BigDecimal.ZERO
219	            : shippingResult.getCost();
220	
221	        BigDecimal insurance = insuranceCalculator.calculate(productsSubtotal, request.getRegion());
222	
223	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
224	
225	        BigDecimal paymentAdjustment = paymentAdjustmentCalculator.calculate(orderTotal, request.getPaymentMethod(), installments, request.getCoupon() != null && !request.getCoupon().isEmpty());
226	        BigDecimal finalTotal = orderTotal.add(paymentAdjustment);
227	
228	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP && finalTotal.compareTo(new BigDecimal("1000.00")) > 0) {
229	            throw new ApiException("PAYMENT_METHOD_UNAVAILABLE", 422);
230	        }
231	    }
232	
233	    private BigDecimal calculateProductsSubtotal(List<OrderItem> items, Map<String, Product> productMap) {
234	        BigDecimal total = BigDecimal.ZERO;
235	        for (OrderItem item : items) {
236	            Product product = productMap.get(item.getSku());
237	            total = total.add(product.getPrice().multiply(new BigDecimal(item.getQuantity())));
238	        }
239	        return total;
240	    }
241	}
