276	    public Order createOrder(CheckoutRequest request) {
277	        try (Connection conn = database.getConnection()) {
278	            conn.setAutoCommit(false);
279	            try {
280	                CheckoutSummary summary = checkoutService.calculateSummary(request, conn);
281	
282	                customerRepository.create(request.getCustomer().getCpf(), request.getCustomer().getEmail(), conn);
283	
284	                Order order = new Order();
285	                order.setId(UUID.randomUUID().toString());
286	                order.setCustomerCpf(request.getCustomer().getCpf());
287	                order.setCustomerEmail(request.getCustomer().getEmail());
288	                order.setItems(new ArrayList<>(request.getItems()));
289	                order.setZipCode(request.getZipCode());
290	                order.setRegion(request.getRegion());
291	                order.setShippingMethod(request.getShippingMethod());
292	                order.setCoupon(request.getCoupon());
293	                order.setPaymentMethod(request.getPaymentMethod());
294	                order.setClubTier(request.getClubTier());
295	                order.setStatus(OrderStatus.AWAITING_PAYMENT);
296	                order.setCreatedAt(Instant.now());
297	                order.setSummary(summary);
298	
299	                orderRepository.save(order, conn);
300	
301	                conn.commit();
302	                return order;
303	            } catch (ApiException e) {
304	                conn.rollback();
305	                throw e;
306	            } catch (Exception e) {
307	                conn.rollback();
308	                throw new RuntimeException("Failed to create order", e);
309	            }
310	        } catch (SQLException e) {
311	            throw new RuntimeException("Database connection failed", e);
312	        }
