401	    public Order shipOrder(String orderId, String trackingCode) {
402	        try (Connection conn = database.getConnection()) {
403	            conn.setAutoCommit(false);
404	            try {
405	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
406	                if (existingOrder.isEmpty()) {
407	                    conn.rollback();
408	                    throw new ApiException("ORDER_NOT_FOUND", 404);
409	                }
410	
411	                Order order = existingOrder.get();
412	
413	                if (trackingCode == null || trackingCode.isEmpty()) {
414	                    conn.rollback();
415	                    throw new ApiException("INVALID_ORDER", 422);
416	                }
417	
418	                if (order.getStatus() != OrderStatus.PAID) {
419	                    conn.rollback();
420	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
421	                }
422	
423	                orderRepository.updateStatus(orderId, OrderStatus.SHIPPED, conn);
424	                orderRepository.updateTrackingCode(orderId, trackingCode, conn);
425	                order.setStatus(OrderStatus.SHIPPED);
426	                order.setTrackingCode(trackingCode);
427	
428	                notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId, conn);
429	
430	                conn.commit();
431	                return order;
432	            } catch (ApiException e) {
433	                conn.rollback();
434	                throw e;
435	            } catch (Exception e) {
436	                conn.rollback();
437	                throw new RuntimeException("Failed to ship order", e);
438	            }
439	        } catch (SQLException e) {
440	            throw new RuntimeException("Database connection failed", e);
441	        }
442	    }
