444	    public Order deliverOrder(String orderId) {
445	        try (Connection conn = database.getConnection()) {
446	            conn.setAutoCommit(false);
447	            try {
448	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
449	                if (existingOrder.isEmpty()) {
450	                    conn.rollback();
451	                    throw new ApiException("ORDER_NOT_FOUND", 404);
452	                }
453	
454	                Order order = existingOrder.get();
455	
456	                if (order.getStatus() != OrderStatus.SHIPPED) {
457	                    conn.rollback();
458	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
459	                }
460	
461	                orderRepository.updateStatus(orderId, OrderStatus.DELIVERED, conn);
462	                order.setStatus(OrderStatus.DELIVERED);
463	
464	                conn.commit();
465	                return order;
466	            } catch (ApiException e) {
467	                conn.rollback();
468	                throw e;
469	            } catch (Exception e) {
470	                conn.rollback();
471	                throw new RuntimeException("Failed to deliver order", e);
472	            }
473	        } catch (SQLException e) {
474	            throw new RuntimeException("Database connection failed", e);
475	        }
476	    }
477	
478	    public Order cancelOrder(String orderId) {
479	        try (Connection conn = database.getConnection()) {
480	            conn.setAutoCommit(false);
481	            try {
482	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
483	                if (existingOrder.isEmpty()) {
484	                    conn.rollback();
485	                    throw new ApiException("ORDER_NOT_FOUND", 404);
486	                }
487	
488	                Order order = existingOrder.get();
489	
490	                if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
491	                    conn.rollback();
492	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
493	                }
494	
495	                if (order.getStatus() == OrderStatus.PAID) {
496	                    Map<String, Integer> skuQuantities = new HashMap<>();
497	                    for (OrderItem item : order.getItems()) {
498	                        skuQuantities.put(item.getSku(), item.getQuantity());
499	                    }
500	                    productRepository.increaseStock(skuQuantities, conn);
501	
502	                    if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
503	                        customerRepository.subtractCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit(), conn);
504	                    }
505	                }
506	
507	                orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
508	                order.setStatus(OrderStatus.CANCELLED);
509	
510	                notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
511	
512	                conn.commit();
513	                return order;
514	            } catch (ApiException e) {
515	                conn.rollback();
516	                throw e;
517	            } catch (Exception e) {
518	                conn.rollback();
519	                throw new RuntimeException("Failed to cancel order", e);
520	            }
521	        } catch (SQLException e) {
522	            throw new RuntimeException("Database connection failed", e);
523	        }
524	    }
525	}
