233	import java.math.BigDecimal;
234	import java.math.RoundingMode;
235	
236	public class PaymentAdjustmentCalculator {
237	    public BigDecimal calculate(BigDecimal orderTotal, PaymentMethod paymentMethod, int installments, boolean hasCoupon) {
238	        return switch (paymentMethod) {
239	            case PIX -> {
240	                if (hasCoupon) {
241	                    yield MoneyUtils.roundMoney(BigDecimal.ZERO);
242	                }
243	                BigDecimal discount = MoneyUtils.roundMoney(orderTotal.multiply(new BigDecimal("0.05")));
244	                yield discount.negate();
245	            }
246	            case BANK_SLIP -> new BigDecimal("3.49");
247	            case CREDIT_CARD -> {
248	                if (installments <= 3) {
249	                    yield MoneyUtils.roundMoney(BigDecimal.ZERO);
250	                }
251	                BigDecimal rate = new BigDecimal("0.0199");
252	                BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
253	                BigDecimal denominator = BigDecimal.ONE.subtract(
254	                    onePlusRate.pow(-installments)
255	                );
256	                BigDecimal installmentAmount = orderTotal.multiply(rate).divide(denominator, 10, RoundingMode.HALF_EVEN);
257	                installmentAmount = MoneyUtils.roundMoney(installmentAmount);
258	                BigDecimal finalTotal = installmentAmount.multiply(new BigDecimal(installments));
259	                yield MoneyUtils.roundMoney(finalTotal.subtract(orderTotal));
260	            }
261	        };
262	    }
263	
264	    public BigDecimal calculateInstallmentAmount(BigDecimal finalTotal, int installments) {
265	        return MoneyUtils.roundMoney(finalTotal.divide(new BigDecimal(installments), 10, RoundingMode.HALF_EVEN));
266	    }
267	}
