278	    private final TransLogClient transLogClient;
279	
280	    public ShippingCalculator(TransLogClient transLogClient) {
281	        this.transLogClient = transLogClient;
282	    }
283	
284	    public ShippingResult calculate(CheckoutRequest request, Map<String, Product> productMap) {
285	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), productMap);
286	
287	        return switch (request.getShippingMethod()) {
288	            case STORE_PICKUP -> new ShippingResult(BigDecimal.ZERO, 1);
289	            case COURIER -> {
290	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
291	                    throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
292	                }
293	                yield new ShippingResult(new BigDecimal("18.00"), 0);
294	            }
295	            case ECONOMY, EXPRESS -> {
296	                try {
297	                    ShippingResult result = transLogClient.quote(
298	                        request.getZipCode(),
299	                        totalWeight,
300	                        request.getShippingMethod(),
301	                        request.getRegion()
302	                    );
303	                    if (result == null) {
304	                        throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
305	                    }
306	                    yield result;
307	                } catch (RuntimeException e) {
308	                    if (e.getMessage().equals("CARRIER_UNAVAILABLE")) {
309	                        throw new ApiException("CARRIER_UNAVAILABLE", 503);
310	                    }
311	                    throw e;
312	                }
313	            }
314	        };
315	    }
316	
317	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> productMap) {
318	        BigDecimal total = BigDecimal.ZERO;
319	        for (OrderItem item : items) {
320	            Product product = productMap.get(item.getSku());
321	            total = total.add(product.getWeightKg().multiply(new BigDecimal(item.getQuantity())));
322	        }
323	        return total;
324	    }
